1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.ConstraintViolation;
7	import jakarta.validation.Validator;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
15	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
16	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
17	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
18	 *
19	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
20	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
21	 * body for {@link BuildOwner} to consume.
22	 */
23	public class ValidateOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException {
27	        List<String> errors = new ArrayList<>();
28	        addIfBlank(errors, "firstName", request.getFirstName());
29	        addIfBlank(errors, "lastName", request.getLastName());
30	        addIfBlank(errors, "address", request.getAddress());
31	        addIfBlank(errors, "city", request.getCity());
32	        normalizeTelephone(errors, request);
33	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
34	            String field = violation.getPropertyPath().toString();
35	            if (!field.isEmpty() && !errors.contains(field)) {
36	                errors.add(field);
37	            }
38	        }
39	        if (!errors.isEmpty()) {
40	            throw new MissingOwnerFieldsException(errors);
41	        }
42	        validated.set(request);
43	    }
44	
45	    private static void addIfBlank(List<String> errors, String name, String value) {
46	        if (value == null || value.isBlank()) {
47	            errors.add(name);
48	        }
49	    }
50	
51	    /**
52	     * Normalize the telephone by removing every non-digit character, then require exactly 10 digits.
53	     * The stripped, 10-digit value is written back onto the request so it is stored and returned as
54	     * {@code telephone}. Anything that is not exactly 10 digits after stripping is a {@code telephone}
55	     * error (400).
56	     */
57	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
58	        String value = request.getTelephone();
59	        String digits = value == null ? "" : value.replaceAll("\\D", "");
60	        if (digits.length() != 10) {
61	            errors.add("telephone");
62	            return;
63	        }
64	        request.setTelephone(digits);
65	    }
66	}
