5	/**
6	 * Raised when a create-owner request is missing (absent) or blank (whitespace only) in one
7	 * or more of the required fields. Checked so it appears in a {@code throws} clause and can be
8	 * routed to its escalation handler, which responds 400 with the offending field names.
9	 */
10	public class MissingOwnerFieldsException extends Exception {
11	
12	    private final List<String> fields;
13	
14	    public MissingOwnerFieldsException(List<String> fields) {
15	        super("Missing or blank required owner fields: " + String.join(", ", fields));
16	        this.fields = List.copyOf(fields);
17	    }
18	
19	    /** The names of the required fields that were missing or blank, in declaration order. */
20	    public List<String> getFields() {
21	        return this.fields;
22	    }
23	}
