30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.PetType;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.repository.OwnerRepository;
34	import org.springframework.samples.petclinic.util.EntityUtils;
35	import org.springframework.stereotype.Repository;
36	
37	import javax.sql.DataSource;
38	import jakarta.transaction.Transactional;
39	import java.util.Collection;
40	import java.util.HashMap;
41	import java.util.List;
42	import java.util.Map;
43	
44	/**
45	 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
46	 *
47	 * @author Ken Krebs
48	 * @author Juergen Hoeller
49	 * @author Rob Harrop
50	 * @author Sam Brannen
51	 * @author Thomas Risberg
52	 * @author Mark Fisher
53	 * @author Antoine Rey
54	 * @author Vitaliy Fedoriv
55	 */
56	@DependsOnDatabaseInitialization
57	@Repository
58	@Profile("jdbc")
59	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
60	
61	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
62	
63	    private SimpleJdbcInsert insertOwner;
64	
65	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
66	
67	        this.insertOwner = new SimpleJdbcInsert(dataSource)
68	            .withTableName("owners")
69	            .usingGeneratedKeyColumns("id");
70	
71	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
72	
73	    }
74	
75	
76	    /**
77	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
78	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
79	     * already loaded.
80	     */
81	    @Override
82	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
83	        Map<String, Object> params = new HashMap<>();
84	        params.put("lastName", lastName + "%");
85	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
86	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName",
87	            params,
88	            BeanPropertyRowMapper.newInstance(Owner.class)
89	        );
90	        loadOwnersPetsAndVisits(owners);
91	        return owners;
92	    }
93	
94	    @Override
95	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
96	        Map<String, Object> params = new HashMap<>();
97	        params.put("lastName", lastName + "%");
98	        params.put("size", pageable.getPageSize());
99	        params.put("offset", pageable.getOffset());
100	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
101	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
102	            params,
103	            BeanPropertyRowMapper.newInstance(Owner.class)
104	        );
105	        loadOwnersPetsAndVisits(owners);
106	        Long total = this.namedParameterJdbcTemplate.queryForObject(
107	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
108	            params,
109	            Long.class
110	        );
111	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
112	    }
113	
114	    /**
115	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
116	     * for the corresponding owner, if not already loaded.
117	     */
118	    @Override
119	    public Owner findById(int id) throws DataAccessException {
120	        Owner owner;
121	        try {
122	            Map<String, Object> params = new HashMap<>();
123	            params.put("id", id);
124	            owner = this.namedParameterJdbcTemplate.queryForObject(
125	                "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE id= :id",
126	                params,
127	                BeanPropertyRowMapper.newInstance(Owner.class)
128	            );
129	        } catch (EmptyResultDataAccessException ex) {
130	            throw new ObjectRetrievalFailureException(Owner.class, id);
131	        }
132	        loadPetsAndVisits(owner);
133	        return owner;
134	    }
135	
136	    public void loadPetsAndVisits(final Owner owner) {
137	        Map<String, Object> params = new HashMap<>();
138	        params.put("id", owner.getId());
139	        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
140	            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
141	            params,
142	            new JdbcPetVisitExtractor()
143	        );
144	        Collection<PetType> petTypes = getPetTypes();
145	        for (JdbcPet pet : pets) {
146	            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
147	            owner.addPet(pet);
148	        }
149	    }
150	
151	    @Override
152	    public void save(Owner owner) throws DataAccessException {
153	        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
154	        if (owner.isNew()) {
155	            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
156	            owner.setId(newKey.intValue());
157	        } else {
158	            this.namedParameterJdbcTemplate.update(
159	                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
160	                    "city=:city, telephone=:telephone WHERE id=:id",
161	                parameterSource);
162	        }
163	    }
164	
165	    public Collection<PetType> getPetTypes() throws DataAccessException {
166	        return this.namedParameterJdbcTemplate.query(
167	            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
168	            BeanPropertyRowMapper.newInstance(PetType.class));
169	    }
170	
171	    /**
172	     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
173	     *
174	     * @param owners the list of owners for whom the pet and visit data should be loaded
175	     * @see #loadPetsAndVisits(Owner)
176	     */
177	    private void loadOwnersPetsAndVisits(List<Owner> owners) {
178	        for (Owner owner : owners) {
179	            loadPetsAndVisits(owner);
180	        }
181	    }
182	
183		@Override
184		public Collection<Owner> findAll() throws DataAccessException {
185			List<Owner> owners = this.namedParameterJdbcTemplate.query(
186		            "SELECT id, first_name, last_name, address, city, telephone FROM owners",
187		            new HashMap<String, Object>(),
188		            BeanPropertyRowMapper.newInstance(Owner.class));
189			for (Owner owner : owners) {
190	            loadPetsAndVisits(owner);
191	        }
192		    return owners;
193		}
194	
195	    @Override
196	    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
197	        Map<String, Object> params = new HashMap<>();
198	        params.put("size", pageable.getPageSize());
199	        params.put("offset", pageable.getOffset());
200	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
201	            "SELECT id, first_name, last_name, address, city, telephone FROM owners ORDER BY id LIMIT :size OFFSET :offset",
202	            params,
203	            BeanPropertyRowMapper.newInstance(Owner.class));
204	        loadOwnersPetsAndVisits(owners);
205	        Long total = this.namedParameterJdbcTemplate.queryForObject(
206	            "SELECT COUNT(*) FROM owners",
207	            params,
208	            Long.class
209	        );
210	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
211	    }
212	
213		@Override
214		@Transactional
215		public void delete(Owner owner) throws DataAccessException {
216			Map<String, Object> ownerParams = new HashMap<>();
217			ownerParams.put("id", owner.getId());
218	        List<Pet> pets = owner.getPets();
219	        // cascade delete pets
220	        for (Pet pet : pets){
221	        	Map<String, Object> petParams = new HashMap<>();
222	        	petParams.put("id", pet.getId());
223	        	// cascade delete visits
224	        	List<Visit> visits = pet.getVisits();
225	            for (Visit visit : visits){
226	            	Map<String, Object> visitParams = new HashMap<>();
227	            	visitParams.put("id", visit.getId());
228	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
229	            }
230	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
231	        }
232	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
233		}
234	
235	
236	}
